// Update alias to point to new version after canary success
const lambda = new AWS.Lambda();

async function promoteVersion(newVersion) {
  await lambda.updateAlias({
    FunctionName: 'stream-consumer',
    Name: 'prod',
    FunctionVersion: newVersion,
    RoutingConfig: {
      AdditionalVersionWeights: { [newVersion]: 0.1 }
    }
  }).promise();
}

async function completePromotion() {
  await lambda.updateAlias({
    FunctionName: 'stream-consumer',
    Name: 'prod',
    FunctionVersion: newVersion
  }).promise();
}
```

